package in.aicon.pocket;
import android.content.Context;import android.graphics.*;import android.view.View;
/** Original on-device charts. Integer money stays in the model; drawing alone uses float. */
final class LedgerChart extends View {
 String firstLabel="1",lastLabel;void axisLabels(String first,String last){firstLabel=first;lastLabel=last;}
 String emptyLabel="No expenses through today",expenseLabel="Expenses";void labels(String empty,String expenses){emptyLabel=empty;expenseLabel=expenses;invalidate();}
 final long[] values;final int[] colours;final int foreground,muted,accent;final boolean donut;final int throughDay;final Paint p=new Paint(3);
 LedgerChart(Context c,long[] values,int[] colours,boolean donut,int throughDay,int fg,int muted,int accent){super(c);this.values=values.clone();this.colours=colours.clone();this.donut=donut;this.throughDay=throughDay;foreground=fg;this.muted=muted;this.accent=accent;}
 @Override protected void onDraw(Canvas c){super.onDraw(c);float d=getResources().getDisplayMetrics().density,w=getWidth(),h=getHeight();long total=0;for(long v:values)total=Math.addExact(total,v);p.setTypeface(AppFonts.face(getContext(),true));if(total==0){p.setColor(muted);p.setTextSize(13*d);c.drawText(emptyLabel,12*d,h/2,p);return;}if(donut){float size=Math.min(w,h)-20*d,cx=w/2,cy=h/2;RectF r=new RectF(cx-size/2,cy-size/2,cx+size/2,cy+size/2);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(24*d);r.inset(15*d,15*d);float start=-90;for(int i=0;i<values.length;i++){float sweep=(float)(values[i]*360.0/(double)total);p.setColor(colours[i%colours.length]);c.drawArc(r,start,Math.max(0,sweep-2),false,p);start+=sweep;}p.setStyle(Paint.Style.FILL);p.setColor(foreground);p.setTextAlign(Paint.Align.CENTER);p.setTextSize(14*d);c.drawText(expenseLabel,cx,cy+5*d,p);p.setTextAlign(Paint.Align.LEFT);return;}float left=8*d,right=w-8*d,top=15*d,bottom=h-30*d;long sum=0,max=0;for(long v:values){sum=Math.addExact(sum,v);max=Math.max(max,sum);}max=Math.max(max,1);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(d);p.setColor((muted&0xffffff)|0x38000000);for(int i=0;i<3;i++){float y=top+(bottom-top)*i/2;c.drawLine(left,y,right,y,p);}Path line=new Path();sum=0;int end=Math.min(values.length,Math.max(1,throughDay));for(int i=0;i<end;i++){sum=Math.addExact(sum,values[i]);float x=left+(right-left)*i/Math.max(1,values.length-1),y=bottom-(bottom-top)*(float)((double)sum/max);if(i==0)line.moveTo(x,y);else line.lineTo(x,y);}Path area=new Path(line);float endX=left+(right-left)*(end-1)/Math.max(1,values.length-1);area.lineTo(endX,bottom);area.lineTo(left,bottom);area.close();p.setStyle(Paint.Style.FILL);p.setShader(new LinearGradient(0,top,0,bottom,new int[]{(accent&0xffffff)|0x50000000,(accent&0xffffff)|0x04000000},null,Shader.TileMode.CLAMP));c.drawPath(area,p);p.setShader(null);p.setStyle(Paint.Style.STROKE);p.setColor(accent);p.setStrokeWidth(2.5f*d);p.setStrokeCap(Paint.Cap.ROUND);p.setStrokeJoin(Paint.Join.ROUND);c.drawPath(line,p);float lastX=left+(right-left)*(end-1)/Math.max(1,values.length-1),lastY=bottom-(bottom-top)*(float)((double)sum/max);p.setStyle(Paint.Style.FILL);c.drawCircle(lastX,lastY,4*d,p);p.setColor(muted);p.setTextSize(11*d);c.drawText(firstLabel,left,h-6*d,p);p.setTextAlign(Paint.Align.RIGHT);c.drawText(lastLabel==null?String.valueOf(values.length):lastLabel,right,h-6*d,p);p.setTextAlign(Paint.Align.LEFT);}
}
